<template><section class="builder-panel outputs-panel"><header class="builder-panel__heading"><strong>◎ Browser Source Outputs</strong><small>Future workflow</small></header><article v-for="item in outputs" :key="item.title"><div><b>{{ item.title }}</b><span>Transparent background · {{ resolution.width }} × {{ resolution.height }}</span><small>{{ item.detail }}</small></div><button @click="$emit('copy')">Copy placeholder</button><button @click="$emit('preview')">Open preview</button></article><p>Recommended OBS Browser Source: width {{ resolution.width }}, height {{ resolution.height }}, shutdown when hidden.</p></section></template>
